#[derive(Clone, Record, ByteRepr, VaArg, FnPtrArg, Default)]
#[byte_size(1)]
pub struct constexpr_char_traits_char_ {}
impl constexpr_char_traits_char_ {
    pub fn eq(mut c1: i8, mut c2: i8) -> bool {
        return ((c1 as i32) == (c2 as i32));
    }
    pub fn lt(mut c1: i8, mut c2: i8) -> bool {
        return ((c1 as i32) < (c2 as i32));
    }
    pub fn compare(mut s1: Ptr<i8>, mut s2: Ptr<i8>, mut n: u64) -> i32 {
        'loop_: while (n != 0) {
            if ({
                let _c1: i8 = (s1.read());
                let _c2: i8 = (s2.read());
                constexpr_char_traits_char_::lt(_c1, _c2)
            }) {
                return -1_i32;
            }
            if ({
                let _c1: i8 = (s2.read());
                let _c2: i8 = (s1.read());
                constexpr_char_traits_char_::lt(_c1, _c2)
            }) {
                return 1;
            }
            {
                {
                    n.prefix_dec();
                    s1.prefix_inc()
                };
                s2.prefix_inc()
            };
        }
        return 0;
    }
    pub fn length(mut s: Ptr<i8>) -> u64 {
        let len: Value<u64> = Rc::new(RefCell::new(0_u64));
        'loop_: while !({
            let _c1: i8 = (s.read());
            let _c2: i8 = 0_i8;
            constexpr_char_traits_char_::eq(_c1, _c2)
        }) {
            (*len.borrow_mut()).prefix_inc();
            s.prefix_inc();
        }
        return (*len.borrow());
    }
}
impl CppMove for constexpr_char_traits_char_ {
    fn cpp_move(src: Ptr<Self>) -> Self {
        src.read()
    }
}
pub fn sign_0(mut x: i32) -> i32 {
    return if (x > 0) {
        1
    } else {
        (if (x < 0) { -1_i32 } else { 0 })
    };
}
pub fn test1_1(
    sv1: std_basic_string_view_char__std_char_traits_char__,
    mut pos1: u64,
    mut n1: u64,
    mut s2: Ptr<i8>,
    mut n2: u64,
    mut expected: i32,
) {
    let sv1: Value<std_basic_string_view_char__std_char_traits_char__> = Rc::new(RefCell::new(sv1));
    if (pos1 <= ({ (*sv1.borrow()).size() })) {
        ({
            cpp2rust_assert_fail_2(
                ({ ({ sign_0(({ (*sv1.borrow()).compare_36(pos1, n1, (s2).clone(), n2) })) }) }
                    == { ({ sign_0(expected) }) }),
            )
        });
    }
}
